window.krepH = (x, z) => { const g = KREPP.hg, n = g.n, fx = Math.min(n - 1.001, Math.max(0, (x - g.o) / g.s)), fz = Math.min(n - 1.001, Math.max(0, (z - g.o) / g.s)), i = fx | 0, j = fz | 0, u = fx - i, v = fz - j, h = g.h; return ((h[j * n + i] * (1 - u) + h[j * n + i + 1] * u) * (1 - v) + (h[(j + 1) * n + i] * (1 - u) + h[(j + 1) * n + i + 1] * u) * v) / 10; };
